/* cards lie down: art and name on the left, actions on the right edge */
.card {
  display: grid;
  grid-template-columns: 64px minmax(0, 1fr) auto;
  align-items: center;
  gap: 0 16px;
  padding: 14px 18px;
}
.card-top { grid-column: 1 / 3; }
.card-actions {
  grid-column: 3;
  grid-row: 1;
  margin-top: 0;
  padding-left: 0;
  justify-content: flex-end;
  flex-wrap: nowrap;
}
.card-art { width: 64px; height: 72px; }
.card-art svg { width: 58px; height: 66px; }
.card:hover { transform: translateY(-2px); box-shadow: var(--lift-2); }

