<script>
window.addEventListener('load', function(){
  var out=[]; var err='';
  window.addEventListener('error', function(e){ err += 'ERR '+e.message+'\\n'; });
  function log(k,v){out.push(k+': '+v);}
  var q=function(s){return document.querySelector(s);};
  var click=function(el){el.dispatchEvent(new MouseEvent('click',{bubbles:true}));};
  var card=function(id){return document.querySelector('.card[data-id="'+id+'"]');};
  var list=function(id){return card(id).closest('ul').id;};
  var seeds=function(i){return document.querySelectorAll('.week-grid .day')[i].querySelectorAll('.seed').length;};
  try{
    click(card('calathea').querySelector('.card-name'));
    log('later card expands', !q('#detail').hidden, 'parent=' + (q('#detail').parentElement.dataset.id||'stage'));
    log('calathea due', card('calathea').querySelector('.due-text').textContent);
    click(card('calathea').querySelector('.btn-snooze'));
    log('snoozed calathea stays later', list('calathea'));
    log('calathea due now', card('calathea').querySelector('.due-text').textContent);
    log('tomorrow seeds', seeds(6));
    // keyboard escape
    document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));
    log('escape closed panel', q('#detail').hidden);
    // keyboard u undo
    document.dispatchEvent(new KeyboardEvent('keydown',{key:'u',bubbles:true}));
    log('u undid snooze', card('calathea').querySelector('.due-text').textContent, 'seeds='+seeds(6));
    // complete all
    ['fern','pothos','cactus','calathea'].forEach(function(id){
      click(card(id).querySelector('.card-name'));
      var b=q('#detail-primary'); if(b&&!b.hidden&&b.textContent!=='Undo') click(b);
    });
    log('done', document.querySelectorAll('#list-done > li').length);
    log('alldone', !q('#alldone').hidden, q('#alldone-stats').textContent);
    log('tally', q('#tally').textContent);
    log('progress', q('#progress-text').textContent);
    log('greet', q('#greet-lede').textContent);
    log('now/later hidden', q('#group-now').hidden+'/'+q('#group-later').hidden);
    click(q('#reset'));
    log('reset', document.querySelectorAll('#list-now > li').length + ' now, ' + document.querySelectorAll('#list-later > li').length + ' later, ' + document.querySelectorAll('#list-done > li').length + ' done');
    log('reset toast', q('#toast-text').textContent);
  }catch(e){ out.push('EXCEPTION: '+e.message); }
  var pre=document.createElement('pre'); pre.setAttribute('data-probe','4'); pre.textContent=err+out.join('\\n'); document.body.appendChild(pre);
});
</script>
'''
open('_p.html','w').write(src.replace('</body>', probe+'</body>'))
